/* =========================================================
   IMAGES DU LOGO — encodées en base64, fragmentées en morceaux
   courts (pur détail technique de transfert de fichier, aucun
   impact sur le rendu final) puis rassemblées ici et appliquées
   aux balises correspondantes.
   ========================================================= */
(function(){
  var BADGE_B64 =
  "" +
  "" +
  "";
  var LOGO_B64 =
  "" +
  "" +
  "" +
  "" +
  "" +
  "" +
  "" +
  "JEmSJEkJMgAnSZIkSZIkSZIkJcgAnCRJkiRJkiRJkpQgA3CSJEmSJEmSJElSggzASZIkSZIkSZIkSQkyACdJkiRJkiRJkiQlyACcJEmSJEmSJEmSlCADcJIkSZIkSZIkSVKCDMBJkiRJkiRJkiRJCTIAJ0mSJEmSJEmSJCXIAJwkSZIkSZIkSZKUIANwkiRJkiRJkiRJUoL+H1aIpTN96eHVAAAAAElFTkSuQmCC";
  var BADGE_URI = "data:image/png;base64," + BADGE_B64;
  var LOGO_URI  = "data:image/png;base64," + LOGO_B64;

  function applyLogos(){
    var ids = ["ogImageMeta","twitterImageMeta"];
    ids.forEach(function(id){
      var el = document.getElementById(id);
      if(el) el.setAttribute("content", BADGE_URI);
    });
    ["faviconLink","appleTouchIconLink"].forEach(function(id){
      var el = document.getElementById(id);
      if(el) el.setAttribute("href", BADGE_URI);
    });
    ["headerBadgeImg","heroBadgeImg"].forEach(function(id){
      var el = document.getElementById(id);
      if(el) el.src = BADGE_URI;
    });
    var footerLogo = document.getElementById("footerLogoImg");
    if(footerLogo) footerLogo.src = LOGO_URI;
  }
  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", applyLogos);
  } else {
    applyLogos();
  }
})();
